a$.rowid<-seq_len(nrow(a));a$agegrp<-factor(ifelse(a$age<40,'20-39',ifelse(a$age<60,'40-59','60+')),levels=c('20-39','40-59','60+'));a$sexcal<-factor(a$sex_male,levels=c(0,1),labels=c('Female','Male'))
cv0<-c('age','sex_male','race','educ','PIR','birth','smoking');basic<-c('.rowid','SDMVSTRA','SDMVPSU','WTFAS2YR','agegrp','sexcal',cv0,'logucr')
