# The calibrated totals are estimated from the full fatty-acid adult sample and treated as fixed.
# This is a constructed exploratory joint-weight analysis, not a released NCHS joint weight.
getx<-function(rr){v<-rr$variable;if(!is.na(rr$detection_category)&&rr$detection_category=='<50% detected'){lc<-rr$lc_variable;return(list(x=ifelse(a[[lc]]%in%c(0,1),as.integer(a[[lc]]==0),NA),scale='Detected versus below LOD'))};list(x=if(rr$transform=='log2')ifelse(a[[v]]>0,log2(a[[v]]),NA)else as.numeric(a[[v]]),scale=if(rr$transform=='log2')'Per doubling'else'Original scale')}
cvfor<-function(rr){cv<-cv0;if(isTRUE(rr$smoking_biomarker))cv<-setdiff(cv,'smoking');if(isTRUE(rr$urinary))cv<-c(cv,'logucr');cv}
fitpair<-function(rr,v,layer,mode,ex){des<-if(mode=='calibrated_joint')caldes[[rr$weight]]else rawdes;ii<-des$variables$.rowid;xx<-ex$x[ii];yy0<-if(layer=='individual')ifelse(a[[v]]>0,log2(a[[v]]),NA)else a[[v]];yy<-yy0[ii];cv<-cvfor(rr)
 row<-data.frame(variable=rr$variable,label=rr$label,family=rr$class,panel_id=rr$panel_id,layer=layer,metabolite=v,mode=mode,exposure_weight=rr$weight,scale=ex$scale,n=0,n_minor=NA,kish_ess=NA,n_psu=NA,n_strata=NA,design_df=NA,residual_df=NA,rank=NA,log2mean=NA,log2sd=NA,beta=NA,se=NA,low=NA,high=NA,p=NA,inference_df=17,status='not_estimated',message='',warning_count=0,warning_message='')
 tryCatch(withCallingHandlers({m<-a$age[ii]>=20&!is.na(a$group[ii])&is.finite(a[[rr$weight]][ii])&a[[rr$weight]][ii]>0&is.finite(xx)&is.finite(yy)&complete.cases(des$variables[,cv]);m[is.na(m)]<-FALSE;row$n<-sum(m);if(sum(m)<20)stop('fewer_than_20_complete_cases');if(length(unique(xx[m]))<2)stop('no_exposure_variation');row$n_minor<-if(ex$scale=='Detected versus below LOD')min(table(xx[m]))else NA;mu<-mean(yy[m]);ss<-sd(yy[m]);if(!is.finite(ss)||ss==0)stop('no_lipid_variation');row$log2mean<-mu;row$log2sd<-ss;des$variables$xx<-xx;des$variables$zz<-(yy-mu)/ss;des$variables$.dom<-m;dd<-subset(des,.dom);ww<-as.numeric(weights(dd));row$kish_ess<-sum(ww)^2/sum(ww^2);row$n_psu<-length(unique(interaction(dd$variables$SDMVSTRA,dd$variables$SDMVPSU)));row$n_strata<-length(unique(dd$variables$SDMVSTRA));row$design_df<-degf(dd)
 ft<-svyglm(as.formula(paste('zz~xx+',paste(cv,collapse='+'))),dd,family=gaussian());bb<-coef(ft)['xx'];se<-sqrt(vcov(ft)['xx','xx']);row$rank<-ft$rank;row$residual_df<-ft$df.residual;row$beta<-unname(bb);row$se<-unname(se);row$low<-unname(bb-qt(.975,17)*se);row$high<-unname(bb+qt(.975,17)*se);row$p<-unname(2*pt(-abs(bb/se),17));row$status<-if(!is.finite(bb)||!is.finite(se)||se<=0||!ft$converged)'unstable'else if(!is.na(row$n_minor)&&row$n_minor<5)'sparse_detection'else if(row$n<=ft$rank+5)'insufficient_residual_information'else'ok'
 },warning=function(w){row$warning_count<<-row$warning_count+1;row$warning_message<<-paste(unique(c(row$warning_message,conditionMessage(w))),collapse=' | ');invokeRestart('muffleWarning')}),error=function(e)row$message<<-conditionMessage(e));row}
