 if(i%%10==0||i==nrow(reg)){cat('Completed',i,'of',nrow(reg),'biomarkers;',counter,'fits; elapsed',round(as.numeric(difftime(Sys.time(),started,units='secs'))),'s\n');flush.console();saveRDS(all,file.path(out,'logs/progress_models_private.rds'))}
}
